# ---------------------------------------------------------------------------
# Structural Integrity Tests
# ---------------------------------------------------------------------------


class TestDockerfileStructure:
    """Validate fundamental Dockerfile syntax and required directives."""

    def test_file_not_empty(self, dockerfile_content: str):
        """Dockerfile must contain at least one instruction."""
        assert dockerfile_content.strip(), "Dockerfile is empty"

    def test_has_from_instruction(self, dockerfile_lines: list[str]):
        """Every valid Dockerfile must start with a FROM instruction."""
        assert any(line.upper().startswith("FROM ") for line in dockerfile_lines), (
            "Missing required 'FROM' instruction"
        )

    def test_has_workdir(self, dockerfile_lines: list[str]):
        """WORKDIR must be explicitly set to avoid default root context."""
        assert any(line.upper().startswith("WORKDIR ") for line in dockerfile_lines), (
            "Missing 'WORKDIR' instruction - required for path isolation"
        )

    def test_has_copy_instructions(self, dockerfile_lines: list[str]):
        """Application code must be copied into the container."""
        copy_instructions = [
            line for line in dockerfile_lines if line.upper().startswith("COPY ")
        ]
        assert len(copy_instructions) >= 1, (
            "No 'COPY' instructions found - application code not transferred"
        )

    def test_has_expose_instruction(self, dockerfile_lines: list[str]):
        """Container must declare its listening port via EXPOSE."""
        assert any(line.upper().startswith("EXPOSE ") for line in dockerfile_lines), (
            "Missing 'EXPOSE' instruction - port not declared"
        )

    def test_has_cmd_instruction(self, dockerfile_lines: list[str]):
        """Container must define a default runtime command."""
        assert any(line.upper().startswith("CMD ") for line in dockerfile_lines), (
            "Missing 'CMD' instruction - no default process defined"
        )


# ---------------------------------------------------------------------------
# Base Image & Dependency Hygiene
# ---------------------------------------------------------------------------


class TestBaseImageAndDependencies:
    """Validate base image pinning and dependency installation strategy."""

    @pytest.mark.parametrize(
        "forbidden_tag",
        ["latest", "slim", "alpine"],
        ids=["latest-tag", "slim-tag", "alpine-tag"],
    )
    def test_base_image_version_pinned(
        self, dockerfile_content: str, forbidden_tag: str
    ):
        """
        Base image must use a specific version tag, not a floating or
        minimal variant that could introduce non-deterministic builds.
        """
        from_match = re.search(r"FROM\s+([^\s]+)", dockerfile_content)
        assert from_match, "No FROM instruction found"
        image_ref = from_match.group(1)
        assert forbidden_tag not in image_ref, (
            f"Base image '{image_ref}' uses forbidden tag '{forbidden_tag}' - "
            "pin to an exact version for reproducible builds"
        )

    def test_requirements_copied_before_source(
        self, dockerfile_lines: list[str]
    ):
        """
        Dependency files must be copied before application source to
        leverage Docker layer caching for faster rebuilds.
        """
        copy_instructions = [
            line for line in dockerfile_lines if line.upper().startswith("COPY ")
        ]
        assert len(copy_instructions) >= 2, (
            "Expected at least two COPY instructions (deps + source) for cache optimization"
        )
        first_copy = copy_instructions[0].lower()
        assert "requirements" in first_copy, (
            f"First COPY instruction '{first_copy}' does not target requirements.txt - "
            "dependency layer caching is broken"
        )

    def test_pip_install_uses_no_cache(
        self, dockerfile_content: str
    ):
        """pip install must use --no-cache-dir to minimize image size."""
        assert "--no-cache-dir" in dockerfile_content, (
            "pip install missing '--no-cache-dir' flag - image bloat risk"
        )

    def test_requirements_are_pinned(
        self, requirements_content: str
    ):
        """
        requirements.txt must pin exact versions (==) for all top-level
        dependencies to ensure deterministic builds.
        """
        if not requirements_content.strip():
            pytest.skip("requirements.txt not present - skipping pinning check")

        unpinned = []
        for line in requirements_content.splitlines():
            line = line.strip()
            if not line or line.startswith("#") or line.startswith("-"):
                continue
            if "==" not in line:
                unpinned.append(line)

        assert not unpinned, (
            f"Unpinned dependencies found (must use '=='): {unpinned}"
        )


# ---------------------------------------------------------------------------
# Runtime Configuration Validation
