class TestRuntimeConfiguration:
    """Validate production-grade runtime settings (Gunicorn/Uvicorn)."""

    def test_cmd_uses_gunicorn(self, dockerfile_content: str):
        """Production container must use Gunicorn, not bare Uvicorn."""
        assert "gunicorn" in dockerfile_content.lower(), (
            "CMD does not reference gunicorn - production concurrency not configured"
        )

    def test_cmd_uses_uvicorn_worker_class(self, dockerfile_content: str):
        """Gunicorn must be configured with the Uvicorn async worker class."""
        assert "uvicorn.workers.UvicornWorker" in dockerfile_content, (
            "Gunicorn missing '--worker-class uvicorn.workers.UvicornWorker' - "
            "async support not enabled"
        )

    def test_cmd_binds_all_interfaces(self, dockerfile_content: str):
        """Server must bind to 0.0.0.0 for external container access."""
        assert "0.0.0.0:8000" in dockerfile_content, (
            "Gunicorn bind address must be '0.0.0.0:8000' - container not externally reachable"
        )

    def test_cmd_specifies_workers(self, dockerfile_content: str):
        """Worker count must be explicitly configured."""
        assert re.search(r"--workers\s+\d+", dockerfile_content), (
            "Gunicorn missing '--workers N' flag - concurrency not configured"
        )

    def test_exposed_port_matches_bind_port(self, dockerfile_content: str):
        """EXPOSE directive must match the Gunicorn bind port."""
        expose_match = re.search(r"EXPOSE\s+(\d+)", dockerfile_content)
        bind_match = re.search(r"--bind\s+0\.0\.0\.0:(\d+)", dockerfile_content)

        assert expose_match, "No EXPOSE directive found"
        assert bind_match, "No bind port found in CMD"

        expose_port = expose_match.group(1)
        bind_port = bind_match.group(1)

        assert expose_port == bind_port, (
            f"Port mismatch: EXPOSE {expose_port} but bind to {bind_port}"
        )


# ---------------------------------------------------------------------------
# Security & Operational Hygiene
# ---------------------------------------------------------------------------


class TestSecurityHygiene:
    """Validate security best practices for container deployment."""

    def test_no_secrets_in_dockerfile(self, dockerfile_content: str):
        """Dockerfile must not contain hardcoded secrets or credentials."""
        secret_patterns = [
            r"(?i)(password|passwd|secret|token|api[_-]?key)\s*[=:]\s*\S+",
            r"(?i)AKIA[0-9A-Z]{16}",  # AWS access key pattern
            r"ghp_[A-Za-z0-9]{36}",    # GitHub personal access token
        ]
        for pattern in secret_patterns:
            matches = re.findall(pattern, dockerfile_content)
            assert not matches, (
                f"Potential secret detected in Dockerfile: {matches}"
            )

    def test_no_privileged_operations(self, dockerfile_content: str):
        """Container must not execute privileged operations at build time."""
        forbidden_ops = ["sudo", "apt-get update", "yum install", "apk add"]
        for op in forbidden_ops:
            assert op not in dockerfile_content.lower(), (
                f"Privileged operation '{op}' found in Dockerfile - "
                "consider multi-stage build or non-root execution"
            )

    def test_workdir_is_isolated(self, dockerfile_content: str):
        """WORKDIR must not be the root filesystem."""
        workdir_match = re.search(r"WORKDIR\s+(\S+)", dockerfile_content)
        assert workdir_match, "No WORKDIR found"
        workdir = workdir_match.group(1)
        assert workdir != "/", (
            "WORKDIR set to '/' - application files pollute root filesystem"
        )

    def test_no_environment_variable_leaks(self, dockerfile_content: str):
        """ENV instructions must not expose sensitive system paths."""
        sensitive_envs = ["PATH", "HOME", "LD_LIBRARY_PATH"]
        for env_var in sensitive_envs:
            assert not re.search(
                rf"ENV\s+{env_var}\s*=", dockerfile_content
            ), f"ENV instruction overrides sensitive variable '{env_var}'"


