class TestPerformanceOptimization:
    """Validate image size and build performance optimizations."""

    def test_single_from_instruction(self, dockerfile_lines: list[str]):
        """
        Single-stage build is acceptable for this application size.
        Multi-stage builds are recommended for compiled dependencies.
        """
        from_count = sum(
            1 for line in dockerfile_lines if line.upper().startswith("FROM ")
        )
        assert from_count == 1, (
            f"Expected single-stage build, found {from_count} FROM instructions"
        )

    def test_no_unnecessary_apt_installs(self, dockerfile_content: str):
        """No apt-get installs should be present (use slim base images)."""
        assert "apt-get install" not in dockerfile_content, (
            "apt-get install found - use python:slim base image instead"
        )

    def test_pip_install_uses_requirements_only(self, dockerfile_content: str):
        """pip install must reference requirements.txt, not inline packages."""
        pip_install_match = re.search(
            r"RUN\s+pip install[^\n]*", dockerfile_content
        )
        assert pip_install_match, "No pip install instruction found"
        assert "requirements.txt" in pip_install_match.group(0), (
            "pip install does not reference requirements.txt - "
            "dependencies not centralized"
        )


